-- Generated by scripts/history_batches/generate.py. Prepare price without replacing source data.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
CREATE TABLE public.price_history_entities(entity_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,player_id text REFERENCES public.players(id) ON DELETE CASCADE,championship_id text REFERENCES public.championships(id) ON DELETE CASCADE,competition_id text NOT NULL DEFAULT 'unknown',season text NOT NULL DEFAULT 'unknown',UNIQUE NULLS NOT DISTINCT(player_id,championship_id,competition_id,season));
CREATE INDEX price_history_scope ON public.price_history_entities(championship_id,competition_id,season,player_id);
CREATE TABLE public.price_history_states(state_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,entity_id bigint NOT NULL REFERENCES public.price_history_entities ON DELETE CASCADE,signature text NOT NULL,value bigint NOT NULL,change bigint,points integer,avg_points numeric,avg_last_five numeric,matches integer,UNIQUE(state_id,entity_id));
CREATE INDEX price_history_state_lookup ON public.price_history_states(entity_id,signature);
CREATE TABLE public.price_history_times(id bigint PRIMARY KEY DEFAULT nextval('public.player_history_id_seq'),entity_id bigint NOT NULL REFERENCES public.price_history_entities ON DELETE CASCADE,state_id bigint NOT NULL,observed_at timestamptz,recorded_at timestamptz DEFAULT now(),source_unique boolean NOT NULL,FOREIGN KEY(state_id,entity_id) REFERENCES public.price_history_states(state_id,entity_id) ON DELETE CASCADE);
CREATE UNIQUE INDEX price_history_source_time ON public.price_history_times(entity_id,observed_at) WHERE source_unique;
CREATE INDEX price_history_observed ON public.price_history_times(entity_id,observed_at,recorded_at,id);
CREATE INDEX price_history_recorded_page ON public.price_history_times(entity_id,recorded_at,id);

CREATE TABLE public.price_migration_status(id boolean PRIMARY KEY DEFAULT true CHECK(id),seeded boolean NOT NULL DEFAULT false,seed_cursor jsonb,completed_at timestamptz);
INSERT INTO public.price_migration_status DEFAULT VALUES;
CREATE TABLE public.price_migration_queue(entity_id bigint PRIMARY KEY REFERENCES public.price_history_entities ON DELETE CASCADE);
CREATE TABLE public.price_migration_verified(entity_id bigint PRIMARY KEY REFERENCES public.price_history_entities ON DELETE CASCADE,source_rows bigint NOT NULL,endpoint_rows bigint NOT NULL,verified_at timestamptz NOT NULL);
ALTER TABLE public.price_history_entities ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.price_history_entities FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.price_history_entities TO service_role;
ALTER TABLE public.price_history_states ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.price_history_states FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.price_history_states TO service_role;
ALTER TABLE public.price_history_times ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.price_history_times FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.price_history_times TO service_role;
ALTER TABLE public.price_migration_status ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.price_migration_status FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.price_migration_status TO service_role;
ALTER TABLE public.price_migration_queue ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.price_migration_queue FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.price_migration_queue TO service_role;
ALTER TABLE public.price_migration_verified ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.price_migration_verified FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.price_migration_verified TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.price_history_entities_entity_id_seq TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.price_history_states_state_id_seq TO service_role;
DO $$ DECLARE columns text; BEGIN
 SELECT string_agg(CASE WHEN attname=ANY(ARRAY['player_id','championship_id','competition_id','season']) THEN 'e.' WHEN attname=ANY(ARRAY['value','change','points','avg_points','avg_last_five','matches']) THEN 's.' ELSE 't.' END||quote_ident(attname),',' ORDER BY attnum) INTO columns
 FROM pg_attribute WHERE attrelid='public.player_history'::regclass AND attnum>0 AND NOT attisdropped;
 EXECUTE 'CREATE VIEW public.price_history_preview WITH(security_invoker=true) AS SELECT '||columns||' FROM public.price_history_times t JOIN public.price_history_entities e USING(entity_id) JOIN public.price_history_states s ON s.state_id=t.state_id';
END $$;
REVOKE ALL ON public.price_history_preview FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.price_history_preview TO service_role;
CREATE FUNCTION public.price_migration_changed() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE item jsonb;r public.player_history; v_entity bigint;
BEGIN
 IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'History migration in progress; TRUNCATE is disabled'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(CASE TG_OP WHEN 'INSERT' THEN jsonb_build_array(to_jsonb(NEW)) WHEN 'DELETE' THEN jsonb_build_array(to_jsonb(OLD)) ELSE jsonb_build_array(to_jsonb(OLD),to_jsonb(NEW)) END) LOOP
 r:=jsonb_populate_record(NULL::public.player_history,item);
 -- Deletes never recreate an entity removed by a parent FK cascade.
 SELECT entity_id INTO v_entity FROM public.price_history_entities e WHERE e.player_id IS NOT DISTINCT FROM r.player_id AND e.championship_id IS NOT DISTINCT FROM r.championship_id AND e.competition_id IS NOT DISTINCT FROM r.competition_id AND e.season IS NOT DISTINCT FROM r.season;
 IF v_entity IS NULL AND TG_OP<>'DELETE' THEN
 INSERT INTO public.price_history_entities(player_id,championship_id,competition_id,season) VALUES(r.player_id,r.championship_id,r.competition_id,r.season) ON CONFLICT DO NOTHING;
 SELECT entity_id INTO v_entity FROM public.price_history_entities e WHERE e.player_id IS NOT DISTINCT FROM r.player_id AND e.championship_id IS NOT DISTINCT FROM r.championship_id AND e.competition_id IS NOT DISTINCT FROM r.competition_id AND e.season IS NOT DISTINCT FROM r.season;
 END IF;
 IF v_entity IS NOT NULL THEN
 INSERT INTO public.price_migration_queue VALUES(v_entity) ON CONFLICT(entity_id) DO UPDATE SET entity_id=excluded.entity_id;
 DELETE FROM public.price_migration_verified WHERE entity_id=v_entity;
 END IF;
 END LOOP;
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION public.price_migration_changed() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER history_migration_changed AFTER INSERT OR UPDATE OR DELETE ON public.player_history FOR EACH ROW EXECUTE FUNCTION public.price_migration_changed();
CREATE TRIGGER history_migration_no_truncate BEFORE TRUNCATE ON public.player_history FOR EACH STATEMENT EXECUTE FUNCTION public.price_migration_changed();
CREATE FUNCTION public.price_migration_seed(p_limit integer DEFAULT 10000) RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE n bigint;cursor_value jsonb;predicate text:='true';
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>20000 THEN RAISE EXCEPTION 'Invalid discovery page size'; END IF;
 PERFORM 1 FROM public.price_migration_status WHERE id FOR UPDATE;
 IF (SELECT seeded FROM public.price_migration_status WHERE id) THEN RETURN 0; END IF;
 SELECT seed_cursor INTO cursor_value FROM public.price_migration_status WHERE id;
 IF cursor_value IS NOT NULL THEN
 SELECT '(id) > ('||string_agg(quote_literal(cursor_value->>k),',' ORDER BY ord)||')' INTO predicate FROM unnest(ARRAY['id']) WITH ORDINALITY AS cols(k,ord);
 END IF;
 CREATE TEMP TABLE IF NOT EXISTS price_seed_page ON COMMIT DROP AS SELECT player_id,championship_id,competition_id,season,id FROM public.player_history WITH NO DATA;
 TRUNCATE pg_temp.price_seed_page;
 EXECUTE 'INSERT INTO pg_temp.price_seed_page SELECT player_id,championship_id,competition_id,season,id FROM public.player_history WHERE '||predicate||' ORDER BY id LIMIT '||p_limit;
 GET DIAGNOSTICS n=ROW_COUNT;
 INSERT INTO public.price_history_entities(player_id,championship_id,competition_id,season) SELECT DISTINCT player_id,championship_id,competition_id,season FROM pg_temp.price_seed_page ON CONFLICT DO NOTHING;
 INSERT INTO public.price_migration_queue SELECT e.entity_id FROM (SELECT DISTINCT player_id,championship_id,competition_id,season FROM pg_temp.price_seed_page) o JOIN public.price_history_entities e ON e.player_id IS NOT DISTINCT FROM o.player_id AND e.championship_id IS NOT DISTINCT FROM o.championship_id AND e.competition_id IS NOT DISTINCT FROM o.competition_id AND e.season IS NOT DISTINCT FROM o.season AND md5(jsonb_build_array(e.player_id,e.championship_id,e.competition_id,e.season)::text)=md5(jsonb_build_array(o.player_id,o.championship_id,o.competition_id,o.season)::text) ON CONFLICT DO NOTHING;
 IF n>0 THEN SELECT to_jsonb(o) INTO cursor_value FROM pg_temp.price_seed_page o ORDER BY id DESC LIMIT 1; END IF;
 UPDATE public.price_migration_status SET seed_cursor=cursor_value,seeded=n<p_limit WHERE id;
 RETURN n;
END $$;
REVOKE ALL ON FUNCTION public.price_migration_seed(integer) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.price_migration_batch(p_limit integer DEFAULT 25,p_budget_ms integer DEFAULT 5000) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE job record;identity jsonb;predicate text;started timestamptz:=clock_timestamp();n integer:=0;src bigint;dst bigint;mismatch boolean;
BEGIN
 IF p_limit<1 OR p_limit>200 OR p_limit IS NULL OR p_budget_ms<1 OR p_budget_ms>20000 OR p_budget_ms IS NULL THEN RAISE EXCEPTION 'Invalid batch bounds'; END IF;
 IF NOT (SELECT seeded AND completed_at IS NULL FROM public.price_migration_status WHERE id) THEN RAISE EXCEPTION 'Migration is not ready for batches'; END IF;
 -- Match cutover lock order and prevent cutover while a batch is active.
 LOCK TABLE public.player_history IN ACCESS SHARE MODE;
 CREATE TEMP TABLE IF NOT EXISTS price_batch_source ON COMMIT DROP AS SELECT * FROM public.player_history WITH NO DATA;
 CREATE TEMP TABLE IF NOT EXISTS price_batch_retained ON COMMIT DROP AS SELECT o.*,NULL::text AS _migration_signature FROM public.player_history o WITH NO DATA;
 FOR job IN SELECT entity_id FROM public.price_migration_queue ORDER BY entity_id LIMIT p_limit FOR UPDATE SKIP LOCKED LOOP
 SELECT to_jsonb(e) INTO identity FROM public.price_history_entities e WHERE entity_id=job.entity_id;
 IF identity IS NULL THEN CONTINUE; END IF;
 SELECT string_agg(format('%I',k)||CASE WHEN identity->>k IS NULL THEN ' IS NULL' ELSE '='||quote_literal(identity->>k) END,' AND ') INTO predicate FROM unnest(ARRAY['player_id','championship_id','competition_id','season']) k;
 TRUNCATE pg_temp.price_batch_source,pg_temp.price_batch_retained;
 EXECUTE 'INSERT INTO pg_temp.price_batch_source SELECT * FROM public.player_history WHERE '||predicate;
 GET DIAGNOSTICS src=ROW_COUNT;
 INSERT INTO pg_temp.price_batch_retained SELECT (original).*,NULL::text FROM (
 SELECT o AS original,(observed_at IS NULL OR NOT isfinite(observed_at) OR player_id IS NULL OR championship_id IS NULL) AS uncertain,ROW(value,change,points,avg_points,avg_last_five,matches) AS fact,
 lag(ROW(value,change,points,avg_points,avg_last_five,matches)) OVER w AS preceding,lead(ROW(value,change,points,avg_points,avg_last_five,matches)) OVER w AS following
 FROM pg_temp.price_batch_source o WINDOW w AS (ORDER BY observed_at,recorded_at,id)
 ) periods WHERE uncertain OR fact IS DISTINCT FROM preceding OR fact IS DISTINCT FROM following;
 GET DIAGNOSTICS dst=ROW_COUNT;
 UPDATE pg_temp.price_batch_retained o SET _migration_signature=md5(jsonb_build_array(o.value,o.change,o.points,o.avg_points,o.avg_last_five,o.matches)::text);
 ANALYZE pg_temp.price_batch_retained(_migration_signature);
 DELETE FROM public.price_history_times WHERE entity_id=job.entity_id;
 DELETE FROM public.price_history_states WHERE entity_id=job.entity_id;
 INSERT INTO public.price_history_states(entity_id,signature,value,change,points,avg_points,avg_last_five,matches) SELECT DISTINCT job.entity_id,o._migration_signature,o.value,o.change,o.points,o.avg_points,o.avg_last_five,o.matches FROM pg_temp.price_batch_retained o;
 INSERT INTO public.price_history_times(entity_id,state_id,id,observed_at,recorded_at,source_unique) SELECT job.entity_id,s.state_id,o.id,o.observed_at,o.recorded_at,o.player_id IS NOT NULL AND o.championship_id IS NOT NULL FROM pg_temp.price_batch_retained o JOIN public.price_history_states s ON s.entity_id=job.entity_id AND s.signature=o._migration_signature AND s.value IS NOT DISTINCT FROM o.value AND s.change IS NOT DISTINCT FROM o.change AND s.points IS NOT DISTINCT FROM o.points AND s.avg_points IS NOT DISTINCT FROM o.avg_points AND s.avg_last_five IS NOT DISTINCT FROM o.avg_last_five AND s.matches IS NOT DISTINCT FROM o.matches;
 -- Full retained-row equality, including IDs, nulls, payloads and timestamp precision.
 EXECUTE 'SELECT EXISTS((SELECT to_jsonb(o)-''_migration_signature'' FROM pg_temp.price_batch_retained o EXCEPT ALL SELECT to_jsonb(v) FROM public.price_history_preview v WHERE '||predicate||') UNION ALL (SELECT to_jsonb(v) FROM public.price_history_preview v WHERE '||predicate||' EXCEPT ALL SELECT to_jsonb(o)-''_migration_signature'' FROM pg_temp.price_batch_retained o))' INTO mismatch;
 IF mismatch THEN RAISE EXCEPTION 'Retained history verification failed'; END IF;
 INSERT INTO public.price_migration_verified VALUES(job.entity_id,src,dst,clock_timestamp()) ON CONFLICT(entity_id) DO UPDATE SET source_rows=excluded.source_rows,endpoint_rows=excluded.endpoint_rows,verified_at=excluded.verified_at;
 DELETE FROM public.price_migration_queue WHERE entity_id=job.entity_id;
 n:=n+1;
 EXIT WHEN extract(epoch FROM clock_timestamp()-started)*1000>=p_budget_ms;
 END LOOP;
 RETURN jsonb_build_object('processed',n,'pending',(SELECT count(*) FROM public.price_migration_queue),'verified',(SELECT count(*) FROM public.price_migration_verified));
END $$;
REVOKE ALL ON FUNCTION public.price_migration_batch(integer,integer) FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
